 if(this.page===0){if(this.wild.tireless)ui.row('Tireless Swing','Recover 3 stamina/sec • 5 minute buff','Rest',()=>{this.closeMenu();this.startCampRest(true);});(['axeLevel','pickaxeLevel'] as const).forEach((tool,i)=>{const l=this.player[tool],cost=l===0?{wood:200}:toolCost(l);row(i?'Pickaxe':'Axe',`${l?toolName(l)+' (Lv '+l+') • '+(i?`${hitsRequired(l,nodes.stone.hp)} hits/stone, ${hitsRequired(l,nodes.iron.hp)} hits/iron`:`${hitsRequired(l,nodes.wood.hp)} hits/tree`)+(l<70?` → ${i?hitsRequired(l+1,nodes.stone.hp)+' hits/stone':hitsRequired(l+1,nodes.wood.hp)+' hits/tree'} next level`:''):'Locked'} • ${cost?resources.filter(r=>cost[r]).map(r=>`${r}: ${this.camp.storage[r]}/${cost[r]}`).join(' • '):'Maximum level'}`,l?'Upgrade':'Buy',()=>{UpgradeSystem.buy(this.player,this.camp,tool);},!!cost&&affordable(cost));if(cost)resources.filter(r=>cost[r]).forEach(r=>ui.progress(`${i?'Pickaxe':'Axe'} — ${r}`,this.camp.storage[r],cost[r]!));});row('Tireless Swing','Axe level 10 • 5000 wood + 1000 stone',this.wild.tireless?'Unlocked':'Unlock',()=>{if(spend(this.camp.storage,{wood:5000,stone:1000}))this.wild.tireless=true;},!this.wild.tireless&&this.player.axeLevel>=10&&affordable({wood:5000,stone:1000}));}
